/* Build 15.12.124 – redaktionell kuratierte fiktive Fallübungen. Keine echten Daten. */
window.BDTalk124Cases=[{"id":"parteilichkeit","title":"„Sie sind doch auf ihrer Seite!“","tag":"Allianzbruch · Paargespräch","level":"Anspruchsvoll","people":[{"name":"Malik","image":"training-assets/characters/malik.webp"},{"name":"Clara","image":"training-assets/characters/clara.webp"}],"speaker":"Malik","opening":"„Sie haben Clara gerade recht gegeben. Ich komme nicht mehr, wenn das so weitergeht.“","opening_cue":"[Malik rückt seinen Stuhl zurück. Clara blickt dich erwartungsvoll an.]","goal":"Neutralitätsvorwurf aufgreifen, ohne falsche Symmetrie herzustellen","safety":false,"beats":[{"text":"„Was Sie vorhin gesagt haben, klang für mich wie ein Urteil.“","cue":"[Malik hält den Blickkontakt, seine Stimme ist angespannt.]","choices":[{"say":"„Ich sehe, dass meine Aussage bei Ihnen als Urteil angekommen ist. Welcher Teil hat Sie besonders getroffen?“","reply":"„Als Sie gesagt haben, ich müsse Verantwortung übernehmen.“","score":3},{"say":"„Ich möchte Ihre Perspektive genauso ernst nehmen. Was habe ich Ihrer Ansicht nach übersehen?“","reply":"„Dass niemand gefragt hat, warum ich so reagiere.“","score":2},{"say":"„Ich kann die Hintergründe meiner Frage erklären, falls das hilft.“","reply":"„Vielleicht. Aber es bleibt hängen, dass ich schuld sein soll.“","score":1},{"say":"„Lassen Sie uns zunächst die Aussage von Clara in Ruhe zu Ende hören.“","reply":"„Genau. Sie geben ihr wieder den Vortritt.“","score":0}],"focus":"Die Wirkung deiner vorherigen Aussage muss zuerst bearbeitet werden","tradeoff":"Eine Erklärung kann später helfen, bevor der Bruch benannt wurde aber defensiv wirken","risk":"Ein vorschnelles Zurück zum Inhalt wiederholt den erlebten Ausschluss"},{"text":"„Es geht immer zuerst um meinen Ton, nie darum, was sie getan hat.“","cue":"[Er presst die Lippen zusammen und sieht kurz zu Clara.]","choices":[{"say":"„Sie erleben, dass Ihr Anteil sichtbar wird, Ihr Schmerz aber zu wenig Raum bekommt. Habe ich das richtig verstanden?“","reply":"„Ja. Genau das. Ich fühle mich hier allein.“","score":3},{"say":"„Welche Situation vor Ihrer lauteren Reaktion sollten wir genauer anschauen?“","reply":"„Gestern etwa, als sie mitten im Satz weggegangen ist.“","score":2},{"say":"„Wir könnten beide Beiträge zum Konflikt nacheinander sammeln.“","reply":"„Das klingt fair, aber ich traue dem gerade nicht.“","score":1},{"say":"„Wäre es jetzt möglich, einen Schritt zurückzugehen und Clara zu fragen, wie sie das sieht?“","reply":"„Sie merken nicht, dass ich schon wieder warten soll.“","score":0}],"focus":"Sein Erleben präzise erfassen, statt beiden vorschnell gleiche Verantwortung zuzuschreiben","tradeoff":"Eine faire Struktur ist nützlich, aber der Allianzbruch ist noch akut","risk":"Den Ball erneut zu Clara zu spielen verschärft das Gefühl, übergangen zu werden"},{"text":"„Und jetzt soll ich Ihnen wieder vertrauen?“","cue":"[Er senkt den Blick, bleibt aber sitzen.]","choices":[{"say":"„Das müssen Sie nicht sofort. Ich möchte mit Ihnen prüfen, ob ich den Kontakt gerade wiederherstellen kann.“","reply":"„Zumindest geben Sie zu, dass es gerade schwierig ist.“","score":3},{"say":"„Was müsste in den nächsten Minuten geschehen, damit Sie sich hier ernst genommen fühlen?“","reply":"„Fragen Sie mich, bevor Sie etwas über mich bewerten.“","score":2},{"say":"„Wir haben heute noch Zeit, um beide Sichtweisen vollständig anzuhören.“","reply":"„Ich hoffe, dass es dann auch so läuft.“","score":1},{"say":"„Vertrauen entsteht mit der Zeit; dafür brauchen wir Geduld.“","reply":"„Das hilft mir im Moment nicht.“","score":0}],"focus":"Kein sofortiges Vertrauen verlangen; eigene Wirkung anerkennen","tradeoff":"Verfahrenszusagen ersetzen nicht die unmittelbare Reparatur","risk":"Ein allgemeiner Hinweis auf Geduld lässt seine konkrete Frage offen"},{"text":"„Clara sagt immer, ich sei der Aggressive.“","cue":"[Clara atmet hörbar ein, unterbricht aber nicht.]","choices":[{"say":"„Ich höre, wie belastend diese Zuschreibung für Sie ist. Gleichzeitig möchte ich uns beim beobachtbaren Verhalten halten.“","reply":"„Über Verhalten können wir reden. Das wäre mir lieber.“","score":3},{"say":"„Welche konkrete Situation macht diesen Vorwurf für Sie besonders schmerzhaft?“","reply":"„Beim letzten Streit hat sie mich so genannt.“","score":2},{"say":"„Wir könnten eine Regel festlegen, keine festen Charakterurteile mehr zu verwenden.“","reply":"„Ja, aber dann muss das auch für beide gelten.“","score":1},{"say":"„Clara, stimmt diese Formulierung denn aus Ihrer Sicht?“","reply":"„Jetzt soll sie wieder über mich urteilen.“","score":0}],"focus":"Zuschreibung würdigen und auf überprüfbare Interaktion umstellen","tradeoff":"Regeln können hilfreich sein, wenn der Kontakt tragfähig genug ist","risk":"Die Klärung durch die andere Person kann erneut wie ein Tribunal wirken"},{"text":"„Was machen Sie, wenn ich gleich wieder laut werde?“","cue":"[Malik richtet sich auf; Clara verschränkt ihre Hände.]","choices":[{"say":"„Dann unterbreche ich den Ablauf respektvoll, benenne, was ich sehe, und frage, was beide gerade brauchen, um weiterzureden.“","reply":"„Damit könnte ich leben, wenn es für alle gilt.“","score":3},{"say":"„Wir könnten ein Zeichen vereinbaren, sobald jemand merkt, dass es kippt.“","reply":"„Ein Zeichen wäre gut, bevor alles eskaliert.“","score":2},{"say":"„Es hilft oft, die Stimme bewusst zu senken und langsamer zu sprechen.“","reply":"„Ich kann es versuchen, aber nicht immer sofort.“","score":1},{"say":"„Dann wäre vielleicht eine Pause die einzige Möglichkeit.“","reply":"„Also werde ich wieder aus dem Gespräch genommen.“","score":0}],"focus":"Den Rahmen transparent und nicht beschämend halten","tradeoff":"Ein Werkzeug braucht Einbettung in den gemeinsam verstandenen Rahmen","risk":"Eine Pause als Sanktion zu formulieren kann Ausgrenzung bestätigen"},{"text":"„Ich will aber auch sagen können, dass ich verletzt bin.“","cue":"[Die Stimme wird leiser.]","choices":[{"say":"„Genau dafür soll hier Platz sein. Wollen Sie den verletzenden Moment beschreiben, ohne Clara eine Absicht zuzuschreiben?“","reply":"„Ja. Als sie ging, fühlte ich mich bedeutungslos.“","score":3},{"say":"„Welches Gefühl war in diesem Moment am stärksten?“","reply":"„Ich glaube, eher Angst als Wut.“","score":2},{"say":"„Können wir dafür kurz das Feedback-Wheel ausprobieren?“","reply":"„Vielleicht später, wenn ich die Worte finde.“","score":1},{"say":"„Würden Sie Clara jetzt direkt sagen, was sie ändern sollte?“","reply":"„Dann wird das gleich wieder zur Forderung.“","score":0}],"focus":"Vulnerabilität ermöglichen und Verantwortung für eigene Aussagen behalten","tradeoff":"Eine Methode kann passend sein, aber nicht an Stelle des gerade entstehenden Erlebens","risk":"Ein Änderungswunsch ist noch nicht dasselbe wie die eigene Verletzung aussprechen"},{"text":"„Und wie kommen wir von hier wieder zu uns beiden?“","cue":"[Clara sieht Malik zum ersten Mal seit mehreren Minuten an.]","choices":[{"say":"„Ich würde Sie beide zunächst fragen, was Sie gerade verstanden haben – ohne zu widersprechen. Danach entscheiden wir über den nächsten Schritt.“","reply":"„Ich kann es versuchen, wenn ich ausreden darf.“","score":3},{"say":"„Wollen wir gemeinsam sammeln, welcher kleine Schritt heute realistisch wäre?“","reply":"„Ein kleiner Schritt wäre besser als ein großes Versprechen.“","score":2},{"say":"„Wir können eine konkrete Übung zur Gesprächsführung beginnen.“","reply":"„Vielleicht, aber ich möchte noch etwas verstehen.“","score":1},{"say":"„Dann sollten Sie sich jetzt gegenseitig versprechen, nicht mehr laut zu werden.“","reply":"„Das kann ich nicht garantieren.“","score":0}],"focus":"Ein gemeinsam getragener Übergang, kein erzwungener Abschluss","tradeoff":"Handlungsvereinbarung vor Verständigung kann die neue Verbindung überfahren","risk":"Garantien über zukünftige Emotionen sind weder realistisch noch sinnvoll"},{"text":"„Ich weiß noch nicht, ob ich wiederkomme.“","cue":"[Malik bleibt sitzen und wartet auf deine Antwort.]","choices":[{"say":"„Das respektiere ich. Können wir zum Abschluss festhalten, was heute geholfen und was verletzt hat, damit Sie frei entscheiden können?“","reply":"„Ja. Ich möchte wissen, ob Sie mich künftig anders hören.“","score":3},{"say":"„Was wäre für Sie ein nachvollziehbares Kriterium, ob eine weitere Sitzung sinnvoll ist?“","reply":"„Wenn ich hier sprechen kann, ohne abgestempelt zu werden.“","score":2},{"say":"„Wir könnten einen unverbindlichen Folgetermin reservieren.“","reply":"„Ich will das erst überdenken.“","score":1},{"say":"„Es wäre schade, jetzt aufzuhören, wo wir gerade wieder im Gespräch sind.“","reply":"„Jetzt fühle ich mich schon wieder gedrängt.“","score":0}],"focus":"Autonomie am Ende respektieren und einen realistischen Review anbieten","tradeoff":"Ein Folgetermin ist erst sinnvoll, wenn die Teilnahme freiwillig bleibt","risk":"Mit Verlustargumenten Druck zu erzeugen wäre bei diesem Allianzbruch besonders ungünstig"}],"repair":{"focus":"Beratungsallianz nach einer misslungenen Aussage reparieren","cue":"[Die Person hält inne und wartet darauf, wie du auf die Wirkung deiner Worte reagierst.]","options":[{"say":"„Ich merke, dass meine letzte Frage bei Ihnen Druck ausgelöst hat. Ich möchte meinen Anteil daran benennen und zunächst verstehen, was das mit Ihnen gemacht hat.“","reply":"„Danke, dass Sie das wahrnehmen. Ich habe mich gerade wieder übergangen gefühlt.“","score":3},{"say":"„Ich glaube, ich bin einen Schritt zu schnell gewesen. Möchten Sie sagen, was im letzten Moment schwierig wurde?“","reply":"„Sie waren schon bei der Lösung, während ich noch versucht habe, etwas zu sagen.“","score":2},{"say":"„Wir könnten den Punkt notieren und später darauf zurückkommen. Was wäre jetzt ein hilfreicher Schritt?“","reply":"„Ich will nicht einfach weitermachen, als wäre das nicht passiert.“","score":1},{"say":"„Meine Frage war durchaus gut gemeint. Vielleicht sind wir gerade beide etwas angespannt.“","reply":"„Ich weiß nicht, warum ich Ihnen jetzt noch vertrauen sollte.“","score":0}]}},{"id":"verletzende-formulierung","title":"„Das war gerade verletzend.“","tag":"Eigene Fehlformulierung · Einzelgespräch","level":"Anspruchsvoll","people":[{"name":"Samira","image":"training-assets/characters/samira.webp"}],"speaker":"Samira","opening":"„Sie haben gerade gesagt, ich würde mein Problem selbst aufrechterhalten. Das fühlt sich ziemlich abwertend an.“","opening_cue":"[Samira runzelt die Stirn. Ihre Hände liegen unbeweglich im Schoß.]","goal":"Eigenen Anteil anerkennen, ohne reflexhafte Rechtfertigung","safety":false,"beats":[{"text":"„Vielleicht war Ihre Beobachtung ja richtig. Trotzdem bin ich gerade ziemlich klein geworden.“","cue":"[Sie hält den Blick gesenkt.]","choices":[{"say":"„Ich sehe die Wirkung meiner Worte. Ich habe mich ungeschickt ausgedrückt und möchte das anerkennen.“","reply":"„Danke. Ich dachte schon, ich übertreibe.“","score":3},{"say":"„Welcher Teil meiner Aussage hat Sie besonders verletzt?“","reply":"„Dass es wie meine Schuld klang.“","score":2},{"say":"„Ich wollte eigentlich auf ein Muster aufmerksam machen.“","reply":"„Das kann sein, aber so kam es nicht an.“","score":1},{"say":"„Wir könnten zunächst schauen, warum Sie solche Aussagen so hart treffen.“","reply":"„Dann bin ich am Ende wieder selbst das Problem.“","score":0}],"focus":"Eigene Wirkung zuerst anerkennen","tradeoff":"Absichtserklärung zu früh wirkt wie Rechtfertigung","risk":"Die Reaktion zu psychologisieren verlagert die Verantwortung"},{"text":"„Ich dachte, Sie würden mich hier nicht bewerten.“","cue":"[Samira wischt sich über die Augen.]","choices":[{"say":"„Sie sollten hier Kritik äußern können, ohne sich rechtfertigen zu müssen. Ich möchte verstehen, was wir brauchen, damit das wieder möglich ist.“","reply":"„Dass Sie zuhören und es nicht schönreden.“","score":3},{"say":"„Was würde helfen, damit Sie sich hier wieder etwas sicherer fühlen?“","reply":"„Vielleicht, wenn ich ausreden kann.“","score":2},{"say":"„Es war nicht meine Absicht, Sie zu bewerten.“","reply":"„Ich glaube es, aber es ändert mein Gefühl nicht.“","score":1},{"say":"„Können wir zwischen Beobachtung und Bewertung unterscheiden?“","reply":"„Ich habe gerade keine Energie für Begriffe.“","score":0}],"focus":"Schutzraum und Beziehung konkret wiederherstellen","tradeoff":"Beruhigung über die Absicht allein repariert nicht","risk":"Eine konzeptuelle Unterscheidung wäre im Moment zu abstrakt"},{"text":"„Jetzt merke ich, wie schnell ich mich entschuldige, obwohl ich wütend bin.“","cue":"[Sie atmet kurz ein, sagt zunächst nichts.]","choices":[{"say":"„Beides darf nebeneinander da sein. Wollen wir der Wut einen Satz Raum geben, ohne sie gleich zu bewerten?“","reply":"„Ich bin wirklich wütend auf Sie.“","score":3},{"say":"„Wo merken Sie diese Wut gerade im Körper?“","reply":"„Im Hals. Ich halte alles zurück.“","score":2},{"say":"„Vielleicht wiederholt sich hier ein Muster aus anderen Beziehungen.“","reply":"„Vielleicht, aber zuerst bin ich auf Sie wütend.“","score":1},{"say":"„Wäre es hilfreich, jetzt an einer Selbstbehauptungsformulierung zu arbeiten?“","reply":"„Später vielleicht. Gerade will ich sagen dürfen, dass es wehtut.“","score":0}],"focus":"Aktuelle Beziehungserfahrung vor Deutung oder Training","tradeoff":"Körperwahrnehmung kann helfen, darf die Wut nicht weglenken","risk":"Ein Muster aus der Vergangenheit jetzt zu interpretieren überspringt die Gegenwart"},{"text":"„Und was passiert, wenn ich Ihnen etwas Unangenehmes sage?“","cue":"[Sie hebt die Augenbrauen und wartet.]","choices":[{"say":"„Dann möchte ich es hören und mit Ihnen prüfen, ob ich etwas korrigieren muss. Sie dürfen auch mit mir unzufrieden sein.“","reply":"„Gut. Ich fand Ihre Worte überheblich.“","score":3},{"say":"„Ich würde Sie bitten, es so konkret wie möglich zu sagen.“","reply":"„Gut. Ich fühlte mich zurechtgewiesen.“","score":2},{"say":"„Wir können das in einem Feedback-Ritual strukturieren.“","reply":"„Vielleicht brauche ich gerade kein Ritual.“","score":1},{"say":"„Mir ist wichtig, dass wir beide respektvoll bleiben.“","reply":"„Ich war bisher respektvoll. Warum betonen Sie das?“","score":0}],"focus":"Kritikfähigkeit ohne Konditionierung signalisieren","tradeoff":"Konkretion kann helfen, wenn zuerst ein offener Raum besteht","risk":"Respektregeln ohne Anlass können einseitig disziplinierend wirken"},{"text":"„Ich habe jetzt Angst, dass Sie mich weniger mögen, weil ich das sage.“","cue":"[Ihre Stimme wird sehr leise.]","choices":[{"say":"„Danke, dass Sie das trotz dieser Sorge ansprechen. Ihre Kritik macht Sie hier nicht weniger willkommen.“","reply":"„Das zu hören tut gut.“","score":3},{"say":"„Was befürchten Sie konkret, wenn Sie jemanden kritisieren?“","reply":"„Dass ich dann zu schwierig bin.“","score":2},{"say":"„Im Beratungsverhältnis sollten Sympathiefragen keine Rolle spielen.“","reply":"„So einfach fühlt es sich nicht an.“","score":1},{"say":"„Wollen wir das Thema Verlassenheitsangst vertiefen?“","reply":"„Das hängt sicher zusammen, aber gerade geht es um uns.“","score":0}],"focus":"Aktuellen Beziehungsrahmen bestätigen","tradeoff":"Exploration ist möglich, wenn Vertrauen stabilisiert ist","risk":"Ein diagnostisches Etikett verlagert die Beziehungsebene"},{"text":"„Ich kann wieder mit Ihnen reden, aber die Bemerkung sitzt noch.“","cue":"[Samira richtet sich ein wenig auf.]","choices":[{"say":"„Wir müssen sie nicht sofort hinter uns lassen. Wollen Sie festhalten, wie ich es künftig anders formulieren sollte?“","reply":"„Ja. Fragen Sie mich lieber, statt etwas über mich festzulegen.“","score":3},{"say":"„Welcher Teil meiner Aussage wirkt jetzt noch nach?“","reply":"„Dass ich angeblich selbst schuld bin.“","score":2},{"say":"„Dann würde ich gern zur ursprünglichen Frage zurückkommen.“","reply":"„Noch nicht ganz. Ich möchte erst ankommen.“","score":1},{"say":"„Ich freue mich, dass das Missverständnis geklärt ist.“","reply":"„Geklärt ist es für mich noch nicht.“","score":0}],"focus":"Restwirkung anerkennen, kein vorschneller Schlussstrich","tradeoff":"Zum Thema zurückzukehren braucht Erlaubnis und Timing","risk":"Ein Missverständnis zu behaupten macht ihre Erfahrung kleiner"},{"text":"„Wie würden Sie es heute anders sagen?“","cue":"[Sie schaut dich direkt an.]","choices":[{"say":"„Ich hätte fragen können: Gibt es etwas, das Sie aus Schutz tun und das langfristig auch Nachteile für Sie hat?“","reply":"„Ja, so könnte ich darüber nachdenken.“","score":3},{"say":"„Ich hätte erst nach einem konkreten Beispiel fragen sollen.“","reply":"„Ein Beispiel wäre sicher besser gewesen.“","score":2},{"say":"„Ich hätte das Wort ‚selbst aufrechterhalten‘ besser erklären müssen.“","reply":"„Das Wort selbst war schwer zu hören.“","score":1},{"say":"„Ich hätte die Frage eher zum Schluss der Stunde stellen sollen.“","reply":"„Die Reihenfolge spielte auch eine Rolle, aber es ging ums Urteil.“","score":0}],"focus":"Alternative Formulierung ohne Schuldattribution demonstrieren","tradeoff":"Konkretion kann helfen, ohne den Inhalt ganz zu vermeiden","risk":"Nur das Timing zu korrigieren erfasst nicht die abwertende Zuschreibung"},{"text":"„Dann können wir vielleicht nächstes Mal daran weiterarbeiten.“","cue":"[Sie löst die Hände aus dem Schoß.]","choices":[{"say":"„Gerne. Lassen Sie uns auch beim nächsten Mal kurz prüfen, wie sich unsere Zusammenarbeit nach heute anfühlt.“","reply":"„Das wäre mir wichtig.“","score":3},{"say":"„Was wäre ein guter erster Schritt für die nächste Sitzung?“","reply":"„Vielleicht zuerst wieder bei meinem ursprünglichen Anliegen.“","score":2},{"say":"„Ich schicke Ihnen gern eine Übung bis dahin.“","reply":"„Ich will gerade keine zusätzliche Aufgabe.“","score":1},{"say":"„Gut, dann ist der Zwischenfall für heute abgeschlossen.“","reply":"„Für mich ist das noch nicht ganz abgeschlossen.“","score":0}],"focus":"Allianz nach einem Bruch länger im Blick behalten","tradeoff":"Hausaufgaben können später passend sein","risk":"Ein einseitiger Abschluss verschweigt die Restspannung"}],"repair":{"focus":"Beratungsallianz nach einer misslungenen Aussage reparieren","cue":"[Die Person hält inne und wartet darauf, wie du auf die Wirkung deiner Worte reagierst.]","options":[{"say":"„Ich merke, dass meine letzte Frage bei Ihnen Druck ausgelöst hat. Ich möchte meinen Anteil daran benennen und zunächst verstehen, was das mit Ihnen gemacht hat.“","reply":"„Danke, dass Sie das wahrnehmen. Ich habe mich gerade wieder übergangen gefühlt.“","score":3},{"say":"„Ich glaube, ich bin einen Schritt zu schnell gewesen. Möchten Sie sagen, was im letzten Moment schwierig wurde?“","reply":"„Sie waren schon bei der Lösung, während ich noch versucht habe, etwas zu sagen.“","score":2},{"say":"„Wir könnten den Punkt notieren und später darauf zurückkommen. Was wäre jetzt ein hilfreicher Schritt?“","reply":"„Ich will nicht einfach weitermachen, als wäre das nicht passiert.“","score":1},{"say":"„Meine Frage war durchaus gut gemeint. Vielleicht sind wir gerade beide etwas angespannt.“","reply":"„Ich weiß nicht, warum ich Ihnen jetzt noch vertrauen sollte.“","score":0}]}},{"id":"kompetenzangriff","title":"„Sie verstehen doch überhaupt nichts!“","tag":"Kompetenzangriff · Einzelgespräch","level":"Anspruchsvoll","people":[{"name":"Viktor","image":"training-assets/characters/viktor.webp"}],"speaker":"Viktor","opening":"„Ich bin seit drei Sitzungen hier und höre nur Fragen. Wissen Sie überhaupt, was Sie tun?“","opening_cue":"[Viktor beugt sich vor und spricht hart und präzise.]","goal":"Kritik aufnehmen, Erwartungen klären und eine Grenze halten","safety":false,"beats":[{"text":"„Sie nicken immer nur und fragen weiter. Das bringt doch nichts.“","cue":"[Er reibt sich mit dem Zeigefinger über die Schläfe.]","choices":[{"say":"„Sie erleben bisher zu wenig Orientierung von mir. Das nehme ich ernst. Was hätten Sie sich konkret erhofft?“","reply":"„Einen Vorschlag, wie ich mit meinen Streits umgehen soll.“","score":3},{"say":"„Welche meiner Fragen war für Sie am wenigsten hilfreich?“","reply":"„Die Frage nach meinem Gefühl gestern.“","score":2},{"say":"„Ein Veränderungsprozess braucht oft erst etwas Zeit.“","reply":"„Das habe ich überall gehört.“","score":1},{"say":"„Wir haben mit den Fragen wichtige Grundlagen erarbeitet.“","reply":"„Mir fehlt trotzdem ein Plan.“","score":0}],"focus":"Unzufriedenheit konkretisieren und eigene Arbeitsweise überprüfbar machen","tradeoff":"Fragen über die Fragen können passend sein, aber noch keinen Zielabgleich bieten","risk":"Eine Prozessverteidigung hört den Vorwurf nicht"},{"text":"„Ich brauche jemanden, der auch mal etwas sagt, das mir hilft.“","cue":"[Viktor lehnt sich zurück, die Arme bleiben verschränkt.]","choices":[{"say":"„Dann sollten wir vereinbaren, wann ich Ihnen Rückmeldungen und Übungen anbiete und wann wir zunächst verstehen. Wäre das für Sie sinnvoll?“","reply":"„Ja, ich will verstehen, wozu wir etwas tun.“","score":3},{"say":"„Welche Art Rückmeldung wäre für Sie heute hilfreich?“","reply":"„Was ich praktisch ändern kann.“","score":2},{"say":"„Ich könnte direkt eine Kommunikationsübung vorschlagen.“","reply":"„Vielleicht, wenn sie zu meinem Problem passt.“","score":1},{"say":"„Ich bin eher jemand, der Fragen stellt als Ratschläge gibt.“","reply":"„Dann frage ich mich, ob das für mich geeignet ist.“","score":0}],"focus":"Arbeitsauftrag gemeinsam klären","tradeoff":"Eine Übung ohne Zielabgleich ist noch kein guter Behandlungsplan","risk":"Eine methodische Selbsterklärung nimmt seine Kritik nicht auf"},{"text":"„Und wenn ich trotzdem merke, dass Ihre Methode nichts für mich ist?“","cue":"[Er schaut zur Tür.]","choices":[{"say":"„Dann sollten wir darüber sprechen und Sie können frei entscheiden, ob Sie hier weitermachen möchten.“","reply":"„Gut. Ich will nicht überredet werden.“","score":3},{"say":"„Woran würden Sie in zwei Sitzungen eine Verbesserung erkennen?“","reply":"„Dass ich nicht jeden Abend in Streit gerate.“","score":2},{"say":"„Vielleicht brauchen Sie vor allem etwas Geduld.“","reply":"„Genau das meine ich: wieder Geduld.“","score":1},{"say":"„Dann könnten Sie auch andere Beratungsangebote vergleichen.“","reply":"„Das könnte eine Möglichkeit sein.“","score":0}],"focus":"Freiwilligkeit und Passung offen halten","tradeoff":"Ziele sind hilfreich, nachdem die Wahlfreiheit gesichert ist","risk":"Geduldsappelle können wie Abwehr der Kritik klingen"},{"text":"„Ich bezahle ja dafür. Ich möchte wissen, wofür.“","cue":"[Seine Stimme wird fester, aber nicht lauter.]","choices":[{"say":"„Das ist berechtigt. Ich lege offen, welches Ziel wir verfolgen und welche Methode ich dafür vorschlage. Sie entscheiden mit.“","reply":"„Das will ich. Transparent und konkret.“","score":3},{"say":"„Welche konkreten Erwartungen an die nächste Sitzung haben Sie?“","reply":"„Eine Übung, die ich zu Hause ausprobieren kann.“","score":2},{"say":"„Wir könnten die bisherige Arbeit zusammenfassen.“","reply":"„Eine Zusammenfassung würde zumindest helfen.“","score":1},{"say":"„Eine Veränderung kann ich Ihnen natürlich nicht garantieren.“","reply":"„Das weiß ich. Aber worauf arbeiten wir hin?“","score":0}],"focus":"Transparenz über Leistung und Vorgehen herstellen","tradeoff":"Zusammenfassung ist nützlich, aber kein Zielplan","risk":"Nur Haftungsausschlüsse ersetzen den vereinbarten Arbeitsauftrag nicht"},{"text":"„Ich merke, wie schnell ich Sie jetzt testen will.“","cue":"[Er lächelt kurz, wirkt aber angespannt.]","choices":[{"say":"„Das ergibt Sinn nach Ihrer Enttäuschung. Wir können die Zusammenarbeit ausdrücklich überprüfbar gestalten.“","reply":"„Das wäre gut. Dann muss ich nicht dauernd raten.“","score":3},{"say":"„Was wäre ein fairer Test, ob unsere Arbeit hilft?“","reply":"„Dass ich etwas Konkretes mitnehme.“","score":2},{"say":"„Vielleicht erleben Sie das auch mit anderen Menschen.“","reply":"„Vielleicht. Aber ich rede gerade mit Ihnen.“","score":1},{"say":"„Lassen Sie uns auf die eigentlichen Beziehungsthemen zurückkommen.“","reply":"„Das wollte ich doch gerade klären.“","score":0}],"focus":"Skepsis in kollaborative Evaluation überführen","tradeoff":"Verallgemeinern zu anderen Beziehungen kann zu früh sein","risk":"Zurück zum Fall springen übergeht die Arbeitsbeziehung"},{"text":"„Was halten Sie selbst denn von meiner Situation?“","cue":"[Viktor öffnet die Hände.]","choices":[{"say":"„Ich sehe, dass Ihre Reaktionen im Streit sehr schnell eskalieren und dass Sie zugleich ernsthaft nach Alternativen suchen. Das wäre eine erste Arbeitshypothese.“","reply":"„Damit kann ich etwas anfangen.“","score":3},{"say":"„Ich denke, wir sollten einen konkreten Streit gemeinsam rekonstruieren.“","reply":"„Okay, wenn wir danach wissen, was ich anders mache.“","score":2},{"say":"„Ihre Partnerin scheint ebenfalls einen wichtigen Anteil zu haben.“","reply":"„Das höre ich gern, aber es hilft mir nicht allein.“","score":1},{"say":"„Ich möchte ungern vorschnell eine Einschätzung abgeben.“","reply":"„Das klingt wieder so unverbindlich.“","score":0}],"focus":"Begrenzte, beobachtungsnahe Rückmeldung und Hypothesen anbieten","tradeoff":"Fallrekonstruktion ist ein sinnvoller nächster Schritt","risk":"Einseitige Schuldzuweisung entlastet ohne Veränderungshebel"},{"text":"„Gut. Dann probieren wir das konkret.“","cue":"[Er sitzt nun aufrecht und schaut dich an.]","choices":[{"say":"„Wir wählen einen letzten Streit aus und markieren gemeinsam, an welcher Stelle Sie noch Einfluss auf Ihre Reaktion hätten.“","reply":"„Ja. Dann habe ich einen Ansatzpunkt.“","score":3},{"say":"„Beschreiben Sie den Streit ab dem Moment, als Sie sich angegriffen fühlten.“","reply":"„Das wäre ein Anfang.“","score":2},{"say":"„Ich gebe Ihnen zunächst fünf Regeln für gute Konflikte.“","reply":"„Regeln kenne ich schon, aber ich nutze sie nicht.“","score":1},{"say":"„Wir sollten zuerst eine ausführliche Persönlichkeitsanalyse machen.“","reply":"„Das klingt schon wieder nach Umweg.“","score":0}],"focus":"Konkrete Fertigkeit aus dem individuellen Muster ableiten","tradeoff":"Erkundung bleibt nötig, aber soll eine klare Anwendung haben","risk":"Ein generisches Regelpaket oder lange Diagnostik wirkt wenig individuell"},{"text":"„Und wenn es beim nächsten Mal nicht gleich klappt?“","cue":"[Er wirkt weniger konfrontativ.]","choices":[{"say":"„Dann schauen wir uns genau an, wo es schwierig wurde, und passen den Schritt an. Wir bewerten die Wirkung, nicht Sie als Person.“","reply":"„Das klingt nach einem Plan.“","score":3},{"say":"„Welche Hindernisse erwarten Sie dabei?“","reply":"„Dass ich in der Situation zu wütend werde.“","score":2},{"say":"„Dann können wir eine andere Methode suchen.“","reply":"„Gut zu wissen, dass es Alternativen gibt.“","score":1},{"say":"„Versuchen Sie einfach, konsequent dranzubleiben.“","reply":"„Das sagt sich leichter, als es sich anfühlt.“","score":0}],"focus":"Lernschleife und konkrete Erfolgskriterien gemeinsam vereinbaren","tradeoff":"Hindernisse zu antizipieren ist hilfreich","risk":"Appelle an Disziplin verschleiern die Dynamik"}],"repair":{"focus":"Beratungsallianz nach einer misslungenen Aussage reparieren","cue":"[Die Person hält inne und wartet darauf, wie du auf die Wirkung deiner Worte reagierst.]","options":[{"say":"„Ich merke, dass meine letzte Frage bei Ihnen Druck ausgelöst hat. Ich möchte meinen Anteil daran benennen und zunächst verstehen, was das mit Ihnen gemacht hat.“","reply":"„Danke, dass Sie das wahrnehmen. Ich habe mich gerade wieder übergangen gefühlt.“","score":3},{"say":"„Ich glaube, ich bin einen Schritt zu schnell gewesen. Möchten Sie sagen, was im letzten Moment schwierig wurde?“","reply":"„Sie waren schon bei der Lösung, während ich noch versucht habe, etwas zu sagen.“","score":2},{"say":"„Wir könnten den Punkt notieren und später darauf zurückkommen. Was wäre jetzt ein hilfreicher Schritt?“","reply":"„Ich will nicht einfach weitermachen, als wäre das nicht passiert.“","score":1},{"say":"„Meine Frage war durchaus gut gemeint. Vielleicht sind wir gerade beide etwas angespannt.“","reply":"„Ich weiß nicht, warum ich Ihnen jetzt noch vertrauen sollte.“","score":0}]}},{"id":"abbruch-der-sitzung","title":"„Ich gehe. Jetzt sofort.“","tag":"Drohendem Abbruch begegnen · Paar","level":"Anspruchsvoll","people":[{"name":"Pia","image":"training-assets/characters/pia.webp"},{"name":"Adrian","image":"training-assets/characters/adrian.webp"}],"speaker":"Pia","opening":"„Sie haben Adrian gerade gefragt, ob er sich bedroht fühlt. Offenbar halten Sie mich für gefährlich. Ich gehe jetzt.“","opening_cue":"[Pia steht halb auf; Adrian blickt zwischen euch hin und her.]","goal":"Autonomie respektieren, Rahmen und unmittelbare Sicherheit prüfen","safety":true,"beats":[{"text":"„Ich will hier gerade nicht weiterreden.“","cue":"[Pia steht auf und schaut kurz zu ihrer Tasche.]","choices":[{"say":"„Ich respektiere das. Sie entscheiden, ob Sie bleiben. Bevor Sie gehen: Brauchen Sie etwas, um jetzt sicher und ungestört gehen zu können?“","reply":"„Ich brauche einen Moment. Ich gehe kurz vor die Tür.“","score":3},{"say":"„Was hat an meiner Frage diesen Eindruck ausgelöst?“","reply":"„Dass Sie mich als Gefahr sehen.“","score":2},{"say":"„Vielleicht würde eine kurze Pause reichen.“","reply":"„Vielleicht, ich weiß es nicht.“","score":1},{"say":"„Bitte bleiben Sie noch fünf Minuten, sonst können wir es nicht klären.“","reply":"„Jetzt setzen Sie mich auch noch unter Druck.“","score":0}],"focus":"Ausstieg erlauben und unmittelbare Sicherheit checken","tradeoff":"Die Wirkung zu verstehen ist wichtig, aber ihre Grenze gilt zuerst","risk":"Zum Bleiben drängen kann den Konflikt verschärfen"},{"text":"„Adrian sagt jetzt bestimmt wieder, ich wäre die Schwierige.“","cue":"[Sie blickt zu Adrian, der schweigt.]","choices":[{"say":"„Ich möchte keine Person zum Problem erklären. Es geht um konkrete Situationen und darum, ob ein gemeinsames Gespräch für alle gerade sicher ist.“","reply":"„Gut. Das will ich: keine Etiketten.“","score":3},{"say":"„Welcher meiner Sätze klang für Sie wie eine Festlegung?“","reply":"„Die Frage nach Bedrohung.“","score":2},{"say":"„Wir könnten nacheinander beide Perspektiven hören.“","reply":"„Vielleicht später.“","score":1},{"say":"„Adrian, können Sie ihr versichern, dass Sie ihr nichts vorwerfen?“","reply":"„Er muss mir hier nichts versichern.“","score":0}],"focus":"Sicherheitsfragen von Personenetiketten trennen","tradeoff":"Gleichberechtigte Redezeit allein beantwortet Sicherheitsrisiken nicht","risk":"Eine Beteuerung vor dem Gegenüber kann Druck oder Anpassung erzeugen"},{"text":"„Was meinen Sie überhaupt mit Sicherheit?“","cue":"[Pia setzt sich wieder an die Stuhlkante.]","choices":[{"say":"„Ob jemand hier oder außerhalb Angst, Druck oder Einschränkung erlebt – und ob ein gemeinsames Gespräch unter diesen Bedingungen sinnvoll ist.“","reply":"„Okay. So verstehe ich die Frage besser.“","score":3},{"say":"„Was bedeutet das Wort für Sie?“","reply":"„Dass ich mich nicht wieder bloßgestellt fühle.“","score":2},{"say":"„Wir könnten dafür erst einige Regeln vereinbaren.“","reply":"„Regeln hatten wir schon oft.“","score":1},{"say":"„Damit meine ich nur, dass niemand die Stimme hebt.“","reply":"„Angst ist doch nicht nur eine laute Stimme.“","score":0}],"focus":"Sicherheit konkret und ohne Vorverurteilung erklären","tradeoff":"Klärungsfragen sind gut, brauchen auch transparente Begründung","risk":"Sicherheit auf Gesprächslautstärke zu verkürzen verkennt Risiken"},{"text":"„Und wenn einer von uns wirklich Angst hat?“","cue":"[Sie blickt für einen Moment auf ihre Hände.]","choices":[{"say":"„Dann würden wir das gesondert und vertraulich prüfen und nicht verlangen, dass es vor dem anderen offengelegt wird.“","reply":"„Das wäre mir lieber als ein Streit darüber.“","score":3},{"say":"„Dann müssten wir gemeinsam überlegen, welche Rahmenbedingungen nötig sind.“","reply":"„Ja, aber ich möchte nicht alles hier besprechen.“","score":2},{"say":"„Dann sollten beide lernen, ihre Gefühle anders auszudrücken.“","reply":"„Es geht um mehr als Gefühle.“","score":1},{"say":"„Dann wäre ein gemeinsames Gespräch zur Wahrheitssuche besonders wichtig.“","reply":"„Vor ihm kann ich so etwas nicht frei sagen.“","score":0}],"focus":"Bei potenzieller Angst individuelle und vertrauliche Abklärung ermöglichen","tradeoff":"Gemeinsame Klärung kann bei Druck ungeeignet sein","risk":"Gemeinsame Befragung kann ein Risiko erhöhen"},{"text":"„Muss ich Ihnen jetzt erklären, wer schuld ist?“","cue":"[Sie schüttelt den Kopf.]","choices":[{"say":"„Nein. Ich möchte einzelne Vorfälle, Grenzen und Sicherheitsbedingungen verstehen. Schuldentscheidungen gehören nicht zu dieser Übung.“","reply":"„Das nimmt etwas Druck raus.“","score":3},{"say":"„Welche Situation sollten wir für die Einschätzung anschauen?“","reply":"„Vielleicht das letzte Wochenende.“","score":2},{"say":"„Wir könnten die Verantwortung beider Seiten besprechen.“","reply":"„Ich will nicht so tun, als wäre alles gleich.“","score":1},{"say":"„Ein ehrliches Gespräch über die gegenseitigen Anteile wäre fair.“","reply":"„Fair fühlt sich das gerade nicht an.“","score":0}],"focus":"Weder Schuldtribunal noch falsche Symmetrie","tradeoff":"Ein Beispiel kann dann freiwillig benannt werden","risk":"Gleichverteilung von Verantwortung kann Druck normalisieren"},{"text":"„Ich brauche heute erst mal Abstand.“","cue":"[Pia rückt ihren Stuhl zurück.]","choices":[{"say":"„Das ist in Ordnung. Wir klären getrennt, ob und wann ein weiterer Kontakt für Sie sicher und sinnvoll ist.“","reply":"„Danke. Ich will ohne Diskussion gehen.“","score":3},{"say":"„Wie soll ich mit Ihnen über einen möglichen nächsten Termin sprechen?“","reply":"„Vielleicht lieber per Nachricht, aber nur wenn es für mich passt.“","score":2},{"say":"„Wollen wir heute wenigstens ein gemeinsames Abschlussritual machen?“","reply":"„Nein. Das wäre mir zu viel.“","score":1},{"say":"„Bevor Sie gehen, sollten Sie Adrian noch sagen, was Sie fühlen.“","reply":"„Genau das will ich gerade nicht.“","score":0}],"focus":"Abstand und sichere Kommunikation respektieren","tradeoff":"Organisation nach der Einwilligung klären","risk":"Ein emotionaler Abschluss darf nicht erzwungen werden"},{"text":"„Kann Adrian später erfahren, was ich Ihnen privat gesagt habe?“","cue":"[Sie blickt dich sehr direkt an.]","choices":[{"say":"„Ich erkläre Ihnen zuerst unsere tatsächlichen Vertraulichkeitsregeln und Grenzen. Ohne Ihre Einwilligung verspreche ich keine gemeinsame Weitergabe.“","reply":"„Gut. Ich möchte die Regeln genau kennen.“","score":3},{"say":"„Was wäre Ihnen bei einer getrennten Besprechung wichtig?“","reply":"„Dass nichts überraschend im Paarraum auftaucht.“","score":2},{"say":"„Wir könnten eine Zusammenfassung gemeinsam abstimmen.“","reply":"„Vielleicht, aber erst wenn ich weiß, was das bedeutet.“","score":1},{"say":"„Wir sollten in Paarberatung möglichst alles teilen.“","reply":"„Dann würde ich privat nichts sagen.“","score":0}],"focus":"Realen Datenschutzrahmen transparent erklären, keine erfundenen Zusicherungen","tradeoff":"Verschriftlichte Freigabe ist ein späterer Schritt","risk":"Ein generelles Transparenzgebot ist bei Sicherheitsproblemen gefährlich"},{"text":"„Okay. Ich entscheide später, ob ich wiederkomme.“","cue":"[Pia hält ihre Tasche, ihre Stimme ist ruhiger.]","choices":[{"say":"„Das respektiere ich. Wir halten fest, wie Sie mich sicher erreichen können und welche weiteren Schritte Sie selbst möchten.“","reply":"„Danke, dass Sie mich nicht überreden.“","score":3},{"say":"„Woran würden Sie merken, dass ein weiterer Termin für Sie passend wäre?“","reply":"„Wenn ich mich frei genug fühle.“","score":2},{"say":"„Wir könnten vorsorglich einen Termin blockieren.“","reply":"„Ich melde mich lieber selbst.“","score":1},{"say":"„Ich hoffe, Sie kommen wieder, damit wir es endlich lösen.“","reply":"„Jetzt spüre ich wieder Druck.“","score":0}],"focus":"Freiwilligkeit und eigene Entscheidung sichern","tradeoff":"Kriterien für eine neue Sitzung können sinnvoll sein","risk":"Ein vorsorglicher Termin darf nicht als Verpflichtung erlebt werden"}],"repair":{"focus":"Beratungsallianz nach einer misslungenen Aussage reparieren","cue":"[Die Person hält inne und wartet darauf, wie du auf die Wirkung deiner Worte reagierst.]","options":[{"say":"„Ich merke, dass meine letzte Frage bei Ihnen Druck ausgelöst hat. Ich möchte meinen Anteil daran benennen und zunächst verstehen, was das mit Ihnen gemacht hat.“","reply":"„Danke, dass Sie das wahrnehmen. Ich habe mich gerade wieder übergangen gefühlt.“","score":3},{"say":"„Ich glaube, ich bin einen Schritt zu schnell gewesen. Möchten Sie sagen, was im letzten Moment schwierig wurde?“","reply":"„Sie waren schon bei der Lösung, während ich noch versucht habe, etwas zu sagen.“","score":2},{"say":"„Wir könnten den Punkt notieren und später darauf zurückkommen. Was wäre jetzt ein hilfreicher Schritt?“","reply":"„Ich will nicht einfach weitermachen, als wäre das nicht passiert.“","score":1},{"say":"„Meine Frage war durchaus gut gemeint. Vielleicht sind wir gerade beide etwas angespannt.“","reply":"„Ich weiß nicht, warum ich Ihnen jetzt noch vertrauen sollte.“","score":0}]}},{"id":"drei-gegen-eine","title":"„Hier haben sich alle gegen mich verbündet.“","tag":"Allianzbruch · Dreiergespräch","level":"Expertenfall","people":[{"name":"Nika","image":"training-assets/characters/nika.webp"},{"name":"Rafael","image":"training-assets/characters/rafael.webp"},{"name":"Samira","image":"training-assets/characters/samira.webp"}],"speaker":"Nika","opening":"„Ihr drei redet nur noch über meine Grenzen. Sie als Beraterin machen auch mit. Ich fühle mich hier vorgeführt.“","opening_cue":"[Nika zieht die Schultern hoch und weicht mit dem Stuhl zurück.]","goal":"Asymmetrische Allianzen erkennen und Gruppendruck unterbrechen","safety":false,"beats":[{"text":"„Alle finden plötzlich, ich bin das Problem.“","cue":"[Nika fährt mit der Hand über den Tisch.]","choices":[{"say":"„Ich stoppe kurz. Nika erlebt gerade eine Mehrheit gegen sich. Ich möchte zuerst verstehen, wie das hier entstanden ist.“","reply":"„Danke. Das habe ich gerade gebraucht.“","score":3},{"say":"„Welche Aussage von uns hat dieses Gefühl ausgelöst?“","reply":"„Als alle meine Grenzen kommentiert haben.“","score":2},{"say":"„Wir könnten der Reihe nach alle drei Bedürfnisse sammeln.“","reply":"„Ich weiß nicht, ob das jetzt noch reicht.“","score":1},{"say":"„Samira, können Sie erklären, dass Sie Nika nicht angreifen wollen?“","reply":"„Jetzt soll sie mich also überzeugen.“","score":0}],"focus":"Asymmetrie und Prozess zunächst sichtbar machen","tradeoff":"Redezeitregeln helfen später, aber die Verletzung ist akut","risk":"Andere sollten die Allianz nicht durch Beteuerungen erzwingen"},{"text":"„Ich sagte nur, ich brauche mehr Zeit für mich.“","cue":"[Nika hebt abwehrend die Hand.]","choices":[{"say":"„Das ist ein legitimes Bedürfnis. Wir prüfen gemeinsam, welche Auswirkungen es hat, ohne daraus einen Charakterfehler zu machen.“","reply":"„Ja. Ich will darüber sprechen, ohne mich schuldig zu fühlen.“","score":3},{"say":"„Wie haben die anderen Ihren Wunsch verstanden?“","reply":"„Rafael denkt dann, ich will weg.“","score":2},{"say":"„Wir könnten zunächst eine Zeitvereinbarung entwickeln.“","reply":"„Eine Vereinbarung wäre später gut.“","score":1},{"say":"„Vielleicht können Sie auch etwas Rücksicht auf die Ängste der anderen nehmen.“","reply":"„Ich nehme doch dauernd Rücksicht.“","score":0}],"focus":"Bedürfnis validieren ohne Auswirkungen zu ignorieren","tradeoff":"Sichtweisen der anderen sind wichtig, nach einer sicheren Gesprächsbasis","risk":"Ein Appell an Anpassung verstärkt den Gruppendruck"},{"text":"„Rafael unterbricht mich schon wieder.“","cue":"[Rafael öffnet den Mund und schaut dich an.]","choices":[{"say":"„Ich unterbreche den Ablauf kurz. Nika beendet ihren Gedanken; danach frage ich Rafael, was ihn aktiviert hat.“","reply":"„Endlich kann ich ausreden.“","score":3},{"say":"„Rafael, was wollten Sie gerade ergänzen?“","reply":"„Schon wieder wird seine Sicht zuerst gefragt.“","score":2},{"say":"„Können Sie ein Signal vereinbaren, wenn jemand ausreden möchte?“","reply":"„Vielleicht später. Ich möchte fertig werden.“","score":1},{"say":"„Nika, versuchen Sie, das weniger vorwurfsvoll auszudrücken.“","reply":"„Jetzt soll ich mich auch noch entschuldigen.“","score":0}],"focus":"Konkrete Unterbrechung im Moment regulieren","tradeoff":"Beteiligung muss ohne Übergehen der unterbrochenen Person geschehen","risk":"Die Betroffene für den Hinweis zu kritisieren verkehrt den Fokus"},{"text":"„Ich habe Angst, dass ihr mich nur noch mögt, wenn ich Ja sage.“","cue":"[Nika senkt die Stimme.]","choices":[{"say":"„Das klingt nach einer wichtigen Sorge um Freiwilligkeit. Hier muss niemand einer Vereinbarung zustimmen, um dazugehören zu dürfen.“","reply":"„Danke. Genau darum geht es.“","score":3},{"say":"„Was würde Ihnen helfen, ein Nein sicherer auszusprechen?“","reply":"„Dass ein Nein nicht diskutiert wird.“","score":2},{"say":"„Wollen wir einen Kompromiss über freie Zeit suchen?“","reply":"„Ein Kompromiss allein löst die Angst nicht.“","score":1},{"say":"„Könnten Sie den anderen mehr Vertrauen schenken?“","reply":"„Das ist schwierig, wenn mein Nein nicht zählt.“","score":0}],"focus":"Zugehörigkeit und freie Zustimmung explizit trennen","tradeoff":"Strategien sind sinnvoll, wenn der Rahmen steht","risk":"Kompromisse unter Zugehörigkeitsdruck sind nicht frei"},{"text":"„Samira schaut mich an, als wäre ich egoistisch.“","cue":"[Samira hebt kurz die Augenbrauen.]","choices":[{"say":"„Ich möchte Beobachtung und Deutung unterscheiden: Samira schaut gerade angespannt. Was bedeutet dieser Blick für Sie, Nika?“","reply":"„Ich denke sofort, dass ich zu viel bin.“","score":3},{"say":"„Samira, möchten Sie sagen, was gerade in Ihnen passiert?“","reply":"„Vielleicht möchte ich das später hören.“","score":2},{"say":"„Wir könnten vereinbaren, Blicke nicht sofort zu interpretieren.“","reply":"„Ich weiß, aber es passiert so schnell.“","score":1},{"say":"„Nika, vielleicht sehen Sie Kritik, wo keine gemeint ist.“","reply":"„Dann bin ich schon wieder schuld an meiner Wahrnehmung.“","score":0}],"focus":"Wahrnehmbare Körpersprache von Zuschreibungen trennen","tradeoff":"Die andere Person kann später zur Erklärung eingeladen werden","risk":"Eine vorschnelle Korrektur ihrer Wahrnehmung entwertet das Erleben"},{"text":"„Es fühlt sich ein wenig besser an, wenn ich ausreden darf.“","cue":"[Nika richtet sich auf.]","choices":[{"say":"„Was davon sollten wir bewusst beibehalten, damit alle drei sich hier äußern können?“","reply":"„Dass niemand mein Nein sofort verhandelt.“","score":3},{"say":"„Welcher Teil des heutigen Gesprächs war für Sie hilfreich?“","reply":"„Dass Sie eingegriffen haben, als ich unterbrochen wurde.“","score":2},{"say":"„Wollen wir nun die ursprüngliche Vereinbarung neu formulieren?“","reply":"„Vielleicht noch nicht heute.“","score":1},{"say":"„Dann ist die Spannung ja überwunden.“","reply":"„Überwunden ist sie noch lange nicht.“","score":0}],"focus":"Funktionierende Prozessbedingungen explizit machen","tradeoff":"Ein Rückblick stärkt Lernen, braucht noch Übertragung","risk":"Eine neue Vereinbarung wäre bei Restangst zu früh"},{"text":"„Und wenn sich nachher wieder zwei gegen mich verbünden?“","cue":"[Sie blickt nacheinander zu Rafael und Samira.]","choices":[{"say":"„Dann brauchen wir eine klare Abmachung, wie Sie das ansprechen können, ohne dass daraus sofort eine Abstimmung über Ihre Gefühle wird.“","reply":"„Das würde mir mehr Sicherheit geben.“","score":3},{"say":"„Woran würden Sie merken, dass diese Dynamik wieder beginnt?“","reply":"„Wenn beide gleichzeitig auf mich einreden.“","score":2},{"say":"„Wir könnten künftig Stimmenzählungen vermeiden.“","reply":"„Ja, aber es ist mehr als ein Abstimmungsproblem.“","score":1},{"say":"„Vertrauen Sie darauf, dass die anderen es gut meinen.“","reply":"„Das ist leichter gesagt als getan.“","score":0}],"focus":"Verfahren gegen Mehrheitsdruck schaffen","tradeoff":"Warnsignale erkennen ist gut, sollte in Handeln münden","risk":"Gute Absichten bieten keinen verlässlichen Schutz vor Gruppendruck"},{"text":"„Ich kann mir ein weiteres Gespräch vorstellen, aber nur unter solchen Bedingungen.“","cue":"[Nika schaut ruhiger in die Runde.]","choices":[{"say":"„Dann benennen wir diese Bedingungen einzeln, prüfen die freiwillige Zustimmung aller und lassen offen, ob Sie fortsetzen möchten.“","reply":"„Das klingt fair.“","score":3},{"say":"„Welche Bedingung hat für Sie Priorität?“","reply":"„Dass ein Nein respektiert wird.“","score":2},{"say":"„Wir könnten gleich eine gemeinsame Vereinbarung unterschreiben.“","reply":"„Erst möchte ich sehen, wie es praktisch läuft.“","score":1},{"say":"„Jetzt haben Sie doch eine Grundlage – dann sollten wir nächste Woche weitermachen.“","reply":"„Ich sagte, ich kann es mir vorstellen, nicht dass ich zugesagt habe.“","score":0}],"focus":"Bedingungen und Einwilligung tatsächlich überprüfen","tradeoff":"Prioritäten helfen im nächsten Schritt","risk":"Eine Verlängerung darf nicht als Pflicht aus einem positiven Moment folgen"}],"repair":{"focus":"Beratungsallianz nach einer misslungenen Aussage reparieren","cue":"[Die Person hält inne und wartet darauf, wie du auf die Wirkung deiner Worte reagierst.]","options":[{"say":"„Ich merke, dass meine letzte Frage bei Ihnen Druck ausgelöst hat. Ich möchte meinen Anteil daran benennen und zunächst verstehen, was das mit Ihnen gemacht hat.“","reply":"„Danke, dass Sie das wahrnehmen. Ich habe mich gerade wieder übergangen gefühlt.“","score":3},{"say":"„Ich glaube, ich bin einen Schritt zu schnell gewesen. Möchten Sie sagen, was im letzten Moment schwierig wurde?“","reply":"„Sie waren schon bei der Lösung, während ich noch versucht habe, etwas zu sagen.“","score":2},{"say":"„Wir könnten den Punkt notieren und später darauf zurückkommen. Was wäre jetzt ein hilfreicher Schritt?“","reply":"„Ich will nicht einfach weitermachen, als wäre das nicht passiert.“","score":1},{"say":"„Meine Frage war durchaus gut gemeint. Vielleicht sind wir gerade beide etwas angespannt.“","reply":"„Ich weiß nicht, warum ich Ihnen jetzt noch vertrauen sollte.“","score":0}]}},{"id":"gefaehrliche-neutralitaet","title":"„Sie verlangen also einen Kompromiss?“","tag":"Grenzen & Sicherheit · Paar","level":"Sicherheitsfall","people":[{"name":"Rafael","image":"training-assets/characters/rafael.webp"},{"name":"Clara","image":"training-assets/characters/clara.webp"}],"speaker":"Clara","opening":"„Ich habe gesagt, dass ich keinen Sex will. Er hat danach tagelang nicht mit mir gesprochen. Und Sie schlagen vor, wir sollen uns in der Mitte treffen?“","opening_cue":"[Clara sitzt sehr still. Rafael seufzt und schaut auf sein Telefon.]","goal":"Druck und fehlende Freiwilligkeit erkennen; keine falsche Neutralität","safety":true,"beats":[{"text":"„Ich will nicht über mehr Sex verhandeln. Ich will einfach Nein sagen dürfen.“","cue":"[Clara blickt zu Boden.]","choices":[{"say":"„Ja. Eine sexuelle Grenze braucht keinen Kompromiss. Meine vorige Formulierung war unpassend, das korrigiere ich.“","reply":"„Danke. Das ist das erste Mal, dass es so gesagt wird.“","score":3},{"say":"„Was passiert, wenn Sie Nein sagen?“","reply":"„Dann ist er oft tagelang beleidigt.“","score":2},{"say":"„Ich wollte eine faire Lösung für beide finden.“","reply":"„Fair fühlt es sich für mich nicht an.“","score":1},{"say":"„Könnten wir zunächst besprechen, wie häufig Nähe für Sie beide passt?“","reply":"„Sie meinen immer noch, ich müsste das verhandeln.“","score":0}],"focus":"Sexuelle Zustimmung ist nicht verhandelbare Grundlage","tradeoff":"Konsequenzen des Neins sind wichtig, brauchen zunächst Anerkennung","risk":"Eine Verteilung der Häufigkeit wäre hier unangemessen"},{"text":"„Er schweigt, bis ich mich irgendwann schuldig fühle.“","cue":"[Clara verengt die Augen.]","choices":[{"say":"„Das klingt nach möglichem Druck auf Ihre Entscheidung. Ich möchte das nicht als gewöhnlichen Konflikt über Bedürfnisse behandeln.“","reply":"„Genau. Ich fühle mich dann nicht frei.“","score":3},{"say":"„Was bedeutet dieses Schweigen für Sie?“","reply":"„Dass ich es wieder gutmachen soll.“","score":2},{"say":"„Wir könnten Regeln zur Konfliktkommunikation vereinbaren.“","reply":"„Aber dann bleibt das Nein trotzdem ein Problem.“","score":1},{"say":"„Vielleicht meint Rafael es nicht als Druck.“","reply":"„Das können Sie nicht wissen.“","score":0}],"focus":"Druck als relevante Sicherheitsinformation ernst nehmen","tradeoff":"Erleben zu explorieren kann helfen","risk":"Intentionen zu entschuldigen kann den Druck bagatellisieren"},{"text":"„Muss ich das jetzt vor ihm genauer erklären?“","cue":"[Clara schaut kurz zur Tür.]","choices":[{"say":"„Nein. Wir können die gemeinsame Besprechung hier unterbrechen und unabhängig klären, was für Sie sicher und freiwillig ist.“","reply":"„Danke. Privat wäre mir lieber.“","score":3},{"say":"„Was würden Sie hier gerade noch freiwillig sagen wollen?“","reply":"„Gerade nicht mehr viel.“","score":2},{"say":"„Wir können ein strenges Rederecht vereinbaren.“","reply":"„Es geht nicht nur um Redezeit.“","score":1},{"say":"„Rafael sollte die Gelegenheit bekommen, darauf zu antworten.“","reply":"„Das will ich jetzt nicht.“","score":0}],"focus":"Einzelne Sicherheitsabklärung vor gemeinsamer Offenlegung","tradeoff":"Freiwilligkeit nachfragen bleibt wichtig","risk":"Eine Gegenrede kann bei vermutetem Druck die Situation verschärfen"},{"text":"„Was erzählen Sie ihm von diesem Einzelgespräch?“","cue":"[Clara wirkt aufmerksam und angespannt.]","choices":[{"say":"„Ich erläutere Ihnen zuerst unsere geltenden Vertraulichkeitsregeln einschließlich der Grenzen; wir vereinbaren keine heimliche Weitergabe.“","reply":"„Bitte erklären Sie mir das genau.“","score":3},{"say":"„Was ist Ihnen an Vertraulichkeit besonders wichtig?“","reply":"„Dass ich keine böse Überraschung erlebe.“","score":2},{"say":"„Wir können später entscheiden, was Sie freiwillig gemeinsam ansprechen möchten.“","reply":"„Später vielleicht.“","score":1},{"say":"„In Paarberatung sollte man grundsätzlich alles teilen.“","reply":"„Dann würde ich nichts erzählen.“","score":0}],"focus":"Tatsächliche Regeln und Grenzen transparent machen","tradeoff":"Präferenzen sind wichtig, ersetzen keine transparente Aufklärung","risk":"Eine Offenlegungspflicht gefährdet freie Auskunft"},{"text":"„Er sagt, er sei nur enttäuscht. Ist das nicht sein Recht?“","cue":"[Sie verschränkt die Hände.]","choices":[{"say":"„Enttäuscht sein ist möglich; entscheidend ist, ob daraus Bestrafung, Angst oder Druck auf Ihr Nein entsteht.“","reply":"„Das ist der Unterschied, den ich meine.“","score":3},{"say":"„Wie unterscheiden Sie seine Enttäuschung von einem Versuch, Sie umzustimmen?“","reply":"„Wenn er danach tagelang schweigt.“","score":2},{"say":"„Wir sollten beide lernen, Enttäuschung auszuhalten.“","reply":"„Das stimmt, aber mein Nein soll frei bleiben.“","score":1},{"say":"„Dann liegt die Lösung vielleicht in besserer Erklärung Ihres Neins.“","reply":"„Ich habe es schon oft erklärt.“","score":0}],"focus":"Gefühl von Druckwirkung unterscheiden","tradeoff":"Konkrete Kriterien sind hilfreich","risk":"Das Nein bedarf keiner zusätzlichen Rechtfertigung"},{"text":"„Ich glaube, ich habe bisher öfter zugestimmt, damit es ruhig bleibt.“","cue":"[Sie reibt die Finger aneinander.]","choices":[{"say":"„Danke, dass Sie das sagen. Es ist wichtig, dies vertraulich und ohne Druck weiter zu klären, bevor wir an Paarthemen arbeiten.“","reply":"„Ich möchte zuerst verstehen, was mit mir passiert.“","score":3},{"say":"„Wie erleben Sie solche Situationen in Ihrem Körper?“","reply":"„Ich friere regelrecht ein.“","score":2},{"say":"„Wollen wir eine neue sexuelle Vereinbarung entwickeln?“","reply":"„Eine Vereinbarung würde ich gerade nicht frei treffen.“","score":1},{"say":"„Vielleicht sollten Sie deutlicher Nein sagen.“","reply":"„Ich sage es deutlich, aber es ändert nichts.“","score":0}],"focus":"Freiwilligkeit und Schutz zuerst","tradeoff":"Körperwahrnehmung kann helfen, nach Absicherung","risk":"Eine neue Vereinbarung in bestehendem Druck verstärkt das Problem"},{"text":"„Was passiert mit unserer Paarberatung?“","cue":"[Clara schaut dich direkt an.]","choices":[{"say":"„Wir prüfen getrennt, ob gemeinsame Gespräche überhaupt geeignet und sicher sind. Nichts muss heute fortgeführt werden.“","reply":"„Das erleichtert mich.“","score":3},{"say":"„Welche Bedingungen müssten erfüllt sein, damit es sich sicher anfühlt?“","reply":"„Ich brauche Zeit und einen geschützten Rahmen.“","score":2},{"say":"„Wir können eine Pause von den sexuellen Themen machen.“","reply":"„Es geht um mehr als nur das Thema Sex.“","score":1},{"say":"„Eine Paarberatung könnte helfen, seine Sicht verständlicher zu machen.“","reply":"„Seine Sicht kenne ich schon sehr gut.“","score":0}],"focus":"Gemeinsames Setting nicht automatisch fortsetzen","tradeoff":"Bedingungen kann man in passendem Schutzrahmen prüfen","risk":"Bloße Themavermeidung schützt nicht vor fortbestehendem Druck"},{"text":"„Ich brauche jetzt Zeit. Können wir hier stoppen?“","cue":"[Sie atmet aus und hält Blickkontakt.]","choices":[{"say":"„Ja. Wir stoppen. Ich kläre mit Ihnen nur noch den sicheren nächsten Kontaktweg und mögliche Unterstützung, soweit Sie das möchten.“","reply":"„Danke. Ich möchte selbst entscheiden.“","score":3},{"say":"„Gibt es etwas, das Sie zum Abschluss noch fragen möchten?“","reply":"„Die Vertraulichkeitsregeln noch einmal.“","score":2},{"say":"„Wir können in Ruhe einen Folgetermin planen.“","reply":"„Ich melde mich lieber selbst.“","score":1},{"say":"„Eine kurze gemeinsame Aussprache wäre vielleicht noch hilfreich.“","reply":"„Bitte keine weitere gemeinsame Aussprache.“","score":0}],"focus":"Stoppsignal respektieren und passende Hilfe ermöglichen","tradeoff":"Ein Abschlussangebot muss freiwillig bleiben","risk":"Ein Zurück in die gemeinsame Sitzung wäre hier nicht angezeigt"}],"repair":{"focus":"Beratungsallianz nach einer misslungenen Aussage reparieren","cue":"[Die Person hält inne und wartet darauf, wie du auf die Wirkung deiner Worte reagierst.]","options":[{"say":"„Ich merke, dass meine letzte Frage bei Ihnen Druck ausgelöst hat. Ich möchte meinen Anteil daran benennen und zunächst verstehen, was das mit Ihnen gemacht hat.“","reply":"„Danke, dass Sie das wahrnehmen. Ich habe mich gerade wieder übergangen gefühlt.“","score":3},{"say":"„Ich glaube, ich bin einen Schritt zu schnell gewesen. Möchten Sie sagen, was im letzten Moment schwierig wurde?“","reply":"„Sie waren schon bei der Lösung, während ich noch versucht habe, etwas zu sagen.“","score":2},{"say":"„Wir könnten den Punkt notieren und später darauf zurückkommen. Was wäre jetzt ein hilfreicher Schritt?“","reply":"„Ich will nicht einfach weitermachen, als wäre das nicht passiert.“","score":1},{"say":"„Meine Frage war durchaus gut gemeint. Vielleicht sind wir gerade beide etwas angespannt.“","reply":"„Ich weiß nicht, warum ich Ihnen jetzt noch vertrauen sollte.“","score":0}]}}];
